window.LECTURE_TIMING_NAM = {"1930-1935":{"duration":224.0,"chapters":[{"title":"Mở đầu: thử thách đầu tiên của Đảng","target":"hero","start":0.0},{"title":"Bối cảnh: khủng hoảng kinh tế và đời sống cùng cực","target":"context","start":10.61},{"title":"Cao trào 1930–1931 và Xô viết Nghệ Tĩnh","target":"movements","start":38.42},{"title":"Luận cương chính trị tháng 10 năm 1930","target":"dossiers","start":85.37},{"title":"Khủng bố trắng và Đại hội lần thứ nhất","target":"congress","start":156.67},{"title":"Kết luận: cuộc tổng diễn tập đầu tiên","target":"results","start":198.41}],"cues":[{"s":0.1,"e":6.01,"c":0,"t":"Các bạn thân mến, một đảng vừa ra đời được thử thách không phải bằng lời tuyên bố, mà bằng thực tiễn đấu tranh."},{"s":5.96,"e":10.61,"c":0,"t":"Chỉ vài tháng sau ngày thành lập, Đảng Cộng sản Việt Nam đã đứng trước thử thách ấy."},{"s":10.71,"e":14.34,"c":1,"t":"Bối cảnh: khủng hoảng kinh tế và đời sống cùng cực."},{"s":14.4,"e":20.82,"c":1,"t":"Từ năm 1929 đến 1933, đại khủng hoảng kinh tế thế giới lan đến Đông Dương."},{"s":20.77,"e":26.84,"c":1,"t":"Thực dân Pháp trút gánh nặng lên nhân dân: tăng sưu thuế, sa thải công nhân, giá nông sản sụt mạnh."},{"s":26.84,"e":29.76,"c":1,"t":"Nông dân mất ruộng, công nhân mất việc."},{"s":29.76,"e":33.56,"c":1,"t":"Sau khởi nghĩa Yên Bái, thực dân tiến hành khủng bố trắng."},{"s":33.56,"e":38.43,"c":1,"t":"Mâu thuẫn xã hội bị đẩy lên cực điểm, ngọn lửa đấu tranh chỉ chờ sự lãnh đạo."},{"s":38.52,"e":43.49,"c":2,"t":"Cao trào 1930–1931 và Xô viết Nghệ Tĩnh."},{"s":43.54,"e":48.59,"c":2,"t":"Từ tháng 2 năm 1930, bãi công, biểu tình nổ ra khắp ba miền."},{"s":48.54,"e":55.79,"c":2,"t":"Ngày 1 tháng 5 năm 1930, lần đầu tiên công nhân và nông dân Việt Nam kỷ niệm ngày Quốc tế Lao động trên quy mô cả nước."},{"s":55.9,"e":58.7,"c":2,"t":"Đỉnh cao là ở Nghệ An và Hà Tĩnh."},{"s":58.65,"e":66.04,"c":2,"t":"Tháng 9 năm 1930, hàng nghìn nông dân Hưng Nguyên biểu tình; thực dân cho máy bay ném bom nhưng phong trào không dừng lại."},{"s":66.04,"e":72.18,"c":2,"t":"Ở nhiều làng xã, bộ máy chính quyền thực dân phong kiến tê liệt, nhân dân tự lập chính quyền theo kiểu Xô viết."},{"s":72.29,"e":79.05,"c":2,"t":"Chính quyền Xô viết chia ruộng công cho dân nghèo, bỏ các thứ thuế vô lý, mở lớp dạy chữ quốc ngữ, bài trừ hủ tục."},{"s":79.0,"e":85.37,"c":2,"t":"Cao trào cho thấy sức mạnh của liên minh công nông, khả năng tổ chức quần chúng và vai trò lãnh đạo thực tế của Đảng mới thành lập."},{"s":85.47,"e":89.01,"c":3,"t":"Luận cương chính trị tháng 10 năm 1930."},{"s":89.07,"e":101.92,"c":3,"t":"Tháng 10 năm 1930, Hội nghị lần thứ nhất Ban Chấp hành Trung ương họp tại Hương Cảng, đổi tên Đảng thành Đảng Cộng sản Đông Dương, thông qua Luận cương chính trị do đồng chí Trần Phú chủ trì khởi thảo, và bầu đồng chí làm Tổng Bí thư đầu tiên."},{"s":101.98,"e":116.61,"c":3,"t":"Luận cương xác định cách mạng Đông Dương trước hết là cách mạng tư sản dân quyền, có tính chất thổ địa và phản đế, sau đó tiến lên chủ nghĩa xã hội, bỏ qua thời kỳ tư bản chủ nghĩa; công nhân và nông dân là hai động lực chính; nhấn mạnh vai trò lãnh đạo của Đảng và phương pháp bạo lực cách mạng."},{"s":116.56,"e":121.1,"c":3,"t":"Luận cương viết: vấn đề thổ địa là cái cốt của cách mạng tư sản dân quyền."},{"s":121.2,"e":136.67,"c":3,"t":"Đây là chỗ các bạn phải đặc biệt chú ý. Luận cương có hạn chế: chưa đặt nhiệm vụ giải phóng dân tộc lên hàng đầu, nặng về đấu tranh giai cấp và cách mạng ruộng đất; đánh giá chưa đúng khả năng cách mạng của tiểu tư sản, tư sản dân tộc và một bộ phận địa chủ; chưa phát triển tư tưởng mặt trận dân tộc thống nhất."},{"s":136.62,"e":142.25,"c":3,"t":"Nguyên nhân là chưa nắm vững đặc điểm xã hội thuộc địa và chịu ảnh hưởng khuynh hướng tả trong Quốc tế Cộng sản."},{"s":142.37,"e":150.94,"c":3,"t":"So sánh nhanh: Cương lĩnh tháng 2 và Luận cương tháng 10 giống nhau ở mục tiêu chống đế quốc, phong kiến, vai trò của Đảng, công nông là lực lượng cơ bản."},{"s":150.89,"e":156.67,"c":3,"t":"Nhưng Cương lĩnh nổi bật tư duy dân tộc và đoàn kết rộng rãi, phù hợp hơn với xã hội thuộc địa Việt Nam."},{"s":156.77,"e":159.48,"c":4,"t":"Khủng bố trắng và Đại hội lần thứ nhất."},{"s":159.53,"e":165.89,"c":4,"t":"Từ năm 1931, thực dân đàn áp cực kỳ khốc liệt, hàng nghìn chiến sĩ bị bắt, bị giết."},{"s":165.84,"e":172.57,"c":4,"t":"Tổng Bí thư Trần Phú hy sinh tháng 9 năm 1931, để lại lời nhắn: hãy giữ vững chí khí chiến đấu."},{"s":172.68,"e":175.36,"c":4,"t":"Nhưng tổ chức Đảng không bị tiêu diệt."},{"s":175.31,"e":179.47,"c":4,"t":"Trong nhà tù, các chiến sĩ biến nơi giam cầm thành trường học cách mạng."},{"s":179.47,"e":187.95,"c":4,"t":"Từ năm 1932 đến 1935, Đảng kiên trì khôi phục cơ sở; năm 1934 lập Ban Chỉ huy ở ngoài."},{"s":187.95,"e":198.41,"c":4,"t":"Tháng 3 năm 1935, Đại hội đại biểu lần thứ nhất của Đảng họp tại Ma Cao, đánh dấu việc phục hồi cơ quan lãnh đạo và phong trào sau tổn thất nặng nề, tạo tiền đề cho giai đoạn vận động mới."},{"s":198.51,"e":201.52,"c":5,"t":"Kết luận: cuộc tổng diễn tập đầu tiên."},{"s":201.58,"e":212.2,"c":5,"t":"Cao trào 1930 đến 1931 khẳng định đường lối và năng lực lãnh đạo của Đảng, hình thành trong thực tế khối liên minh công nông, và là cuộc tổng diễn tập đầu tiên cho Cách mạng Tháng Tám."},{"s":212.26,"e":224.09,"c":5,"t":"Bài học: đường lối chỉ phát huy hiệu quả khi xuất phát từ mâu thuẫn chủ yếu và cấu trúc xã hội cụ thể của Việt Nam; sức mạnh cách mạng không chỉ ở tinh thần dũng cảm, mà còn ở khả năng bảo toàn lực lượng và xây dựng mặt trận rộng rãi."}]},"1936-1939":{"duration":169.1,"chapters":[{"title":"Mở đầu: mục tiêu không đổi, sách lược linh hoạt","target":"hero","start":0.0},{"title":"Bối cảnh: nguy cơ phát xít và thời cơ công khai","target":"context","start":18.77},{"title":"Hội nghị Trung ương tháng 7 năm 1936","target":"dossiers","start":52.68},{"title":"Phong trào dân chủ sôi nổi","target":"movements","start":93.0},{"title":"Kết luận: cuộc tổng diễn tập thứ hai","target":"results","start":126.38}],"cues":[{"s":0.1,"e":9.04,"c":0,"t":"Có một câu hỏi đề thi hay khai thác: vì sao những năm 1936 đến 1939, Đảng tạm gác khẩu hiệu đánh đổ đế quốc Pháp và tịch thu ruộng đất?"},{"s":8.99,"e":11.33,"c":0,"t":"Phải chăng Đảng đã đổi mục tiêu?"},{"s":11.33,"e":12.52,"c":0,"t":"Không."},{"s":12.52,"e":18.77,"c":0,"t":"Đây là nghệ thuật lãnh đạo: mục tiêu chiến lược không đổi, nhưng nhiệm vụ trước mắt và sách lược phải linh hoạt theo tình hình."},{"s":18.87,"e":22.47,"c":1,"t":"Bối cảnh: nguy cơ phát xít và thời cơ công khai."},{"s":22.52,"e":27.7,"c":1,"t":"Chủ nghĩa phát xít lên cầm quyền ở Đức, Ý, Nhật, đe dọa chiến tranh thế giới."},{"s":27.65,"e":33.68,"c":1,"t":"Đại hội lần thứ bảy Quốc tế Cộng sản năm 1935 chủ trương lập mặt trận nhân dân chống phát xít."},{"s":33.68,"e":42.01,"c":1,"t":"Năm 1936, Mặt trận Nhân dân lên cầm quyền ở Pháp, nới rộng một số quyền tự do dân chủ ở thuộc địa, thả một số tù chính trị."},{"s":42.12,"e":48.2,"c":1,"t":"Trong nước, đời sống nhân dân vẫn cực khổ, ai cũng khao khát cơm áo, tự do, dân chủ."},{"s":48.15,"e":52.66,"c":1,"t":"Kẻ thù trước mắt, cụ thể nhất, là bọn phản động thuộc địa và tay sai."},{"s":52.78,"e":56.53,"c":2,"t":"Hội nghị Trung ương tháng 7 năm 1936."},{"s":56.6,"e":63.24,"c":2,"t":"Tháng 7 năm 1936, Hội nghị Ban Chấp hành Trung ương họp ở Thượng Hải do đồng chí Lê Hồng Phong chủ trì."},{"s":63.19,"e":74.02,"c":2,"t":"Mục tiêu chiến lược vẫn là chống đế quốc, chống phong kiến; nhưng nhiệm vụ trước mắt là chống phản động thuộc địa, chống phát xít, chống chiến tranh, đòi tự do, dân chủ, cơm áo và hòa bình."},{"s":74.14,"e":82.44,"c":2,"t":"Để tập hợp lực lượng rộng rãi nhất, Đảng lập Mặt trận Thống nhất Nhân dân phản đế Đông Dương, năm 1938 đổi thành Mặt trận Dân chủ Đông Dương."},{"s":82.39,"e":92.99,"c":2,"t":"Hình thức đấu tranh chuyển mạnh sang công khai, nửa công khai, hợp pháp, nửa hợp pháp, khai thác báo chí, mít tinh, nghị trường, kiến nghị, đồng thời vẫn giữ tổ chức bí mật của Đảng."},{"s":93.1,"e":95.47,"c":3,"t":"Phong trào dân chủ sôi nổi."},{"s":95.52,"e":101.0,"c":3,"t":"Phong trào Đông Dương Đại hội lập các ủy ban hành động để thu thập nguyện vọng dân sinh, dân chủ."},{"s":100.95,"e":105.71,"c":3,"t":"Tiếp đó là những cuộc đón rước phái viên Chính phủ Pháp, bãi công, biểu tình."},{"s":105.82,"e":113.13,"c":3,"t":"Báo chí công khai của Đảng như Tiền Phong, Dân Chúng, Lao Động truyền bá chủ nghĩa Mác Lênin và đường lối của Đảng tới đông đảo quần chúng."},{"s":113.08,"e":119.58,"c":3,"t":"Đảng đưa người ra tranh cử vào Viện dân biểu, Hội đồng quản hạt, dùng diễn đàn hợp pháp để bảo vệ quyền lợi nhân dân."},{"s":119.58,"e":126.37,"c":3,"t":"Đỉnh cao là cuộc mít tinh ngày 1 tháng 5 năm 1938 tại khu Đấu xảo Hà Nội với khoảng hai vạn rưỡi người tham gia."},{"s":126.48,"e":129.45,"c":4,"t":"Kết luận: cuộc tổng diễn tập thứ hai."},{"s":129.51,"e":136.6,"c":4,"t":"Tháng 9 năm 1939, Chiến tranh thế giới thứ hai bùng nổ, thực dân Pháp quay lại đàn áp, phong trào kết thúc."},{"s":136.55,"e":144.54,"c":4,"t":"Nhưng Đảng đã có một đội quân chính trị quần chúng hùng hậu, một lớp cán bộ đông đảo, kinh nghiệm xây dựng mặt trận và trưởng thành rõ rệt về nghệ thuật chỉ đạo."},{"s":144.54,"e":149.45,"c":4,"t":"Vì vậy, phong trào dân chủ được coi là cuộc tổng diễn tập thứ hai cho Cách mạng Tháng Tám."},{"s":149.55,"e":152.3,"c":4,"t":"Ba bài học sách lược các bạn cần nhớ."},{"s":152.25,"e":158.2,"c":4,"t":"Một là, mục tiêu chiến lược và nhiệm vụ trước mắt không đồng nhất; phải chọn khâu tập hợp được lực lượng rộng nhất."},{"s":158.2,"e":162.44,"c":4,"t":"Hai là, hình thức đấu tranh phải linh hoạt theo điều kiện chính trị cụ thể."},{"s":162.44,"e":169.05,"c":4,"t":"Ba là, mặt trận rộng rãi không làm mất vai trò lãnh đạo, mà đòi hỏi Đảng phải có năng lực định hướng và tổ chức tốt hơn."}]},"1939-1945":{"duration":270.9,"chapters":[{"title":"Mở đầu: mười lăm ngày làm nên lịch sử","target":"hero","start":0.0},{"title":"Bối cảnh: chiến tranh và ách hai tròng","target":"context","start":12.36},{"title":"Ba Hội nghị Trung ương: 6, 7 và 8","target":"dossiers","start":43.7},{"title":"Chuẩn bị lực lượng và cao trào kháng Nhật","target":"movements","start":118.8},{"title":"Chớp thời cơ: Tổng khởi nghĩa Tháng Tám","target":"expert","start":156.96},{"title":"Tuyên ngôn Độc lập","target":"declaration","start":204.53},{"title":"Kết luận: nguyên nhân và ý nghĩa","target":"results","start":239.26}],"cues":[{"s":0.1,"e":6.69,"c":0,"t":"Tháng 8 năm 1945, chỉ trong khoảng mười lăm ngày, cả dân tộc vùng lên giành chính quyền trên toàn quốc."},{"s":6.64,"e":12.35,"c":0,"t":"Nhưng thắng lợi ấy được chuẩn bị suốt mười lăm năm, đặc biệt là sáu năm chuyển hướng chiến lược đầy bản lĩnh."},{"s":12.46,"e":15.43,"c":1,"t":"Bối cảnh: chiến tranh và ách hai tròng."},{"s":15.48,"e":20.14,"c":1,"t":"Tháng 9 năm 1939, Chiến tranh thế giới thứ hai bùng nổ."},{"s":20.09,"e":25.6,"c":1,"t":"Thực dân Pháp thi hành chính sách kinh tế chỉ huy, vơ vét sức người, sức của cho chiến tranh."},{"s":25.6,"e":32.88,"c":1,"t":"Tháng 9 năm 1940, phát xít Nhật vào Đông Dương, Pháp cấu kết với Nhật, nhân dân ta chịu cảnh một cổ hai tròng."},{"s":32.98,"e":37.55,"c":1,"t":"Mâu thuẫn giữa dân tộc Việt Nam với đế quốc, phát xít Pháp Nhật trở nên gay gắt."},{"s":37.5,"e":43.69,"c":1,"t":"Nhiệm vụ dân sinh, dân chủ không còn đủ đáp ứng yêu cầu lịch sử; vấn đề sống còn là độc lập dân tộc."},{"s":43.8,"e":47.45,"c":2,"t":"Ba Hội nghị Trung ương: 6, 7 và 8."},{"s":47.5,"e":62.2,"c":2,"t":"Hội nghị Trung ương 6, tháng 11 năm 1939, do Tổng Bí thư Nguyễn Văn Cừ chủ trì, mở đầu chuyển hướng: đặt nhiệm vụ giải phóng dân tộc lên hàng đầu, tạm gác khẩu hiệu cách mạng ruộng đất, thay khẩu hiệu chính quyền, lập Mặt trận thống nhất dân tộc phản đế Đông Dương."},{"s":62.15,"e":72.69,"c":2,"t":"Hội nghị Trung ương 7, tháng 11 năm 1940, tiếp tục chuyển hướng, nhấn mạnh chuẩn bị khởi nghĩa vũ trang, duy trì lực lượng Bắc Sơn và hoãn khởi nghĩa Nam Kỳ khi điều kiện chưa chín muồi."},{"s":72.8,"e":81.92,"c":2,"t":"Đỉnh cao là Hội nghị Trung ương 8, tháng 5 năm 1941, tại Pác Bó, Cao Bằng, do Nguyễn Ái Quốc chủ trì sau ba mươi năm Người trở về Tổ quốc."},{"s":81.87,"e":92.25,"c":2,"t":"Hội nghị khẳng định: nếu không giải quyết được vấn đề dân tộc giải phóng, thì chẳng những toàn thể quốc gia dân tộc còn chịu mãi kiếp ngựa trâu, mà quyền lợi của bộ phận, giai cấp đến vạn năm cũng không đòi lại được."},{"s":92.36,"e":96.44,"c":2,"t":"Thứ nhất, giải phóng dân tộc là nhiệm vụ trước hết, trên hết."},{"s":96.39,"e":100.59,"c":2,"t":"Thứ hai, giải quyết vấn đề dân tộc trong khuôn khổ từng nước Đông Dương."},{"s":100.59,"e":106.51,"c":2,"t":"Thứ ba, thành lập Mặt trận Việt Nam Độc lập Đồng minh, gọi tắt là Việt Minh, để đoàn kết toàn dân."},{"s":106.51,"e":112.86,"c":2,"t":"Thứ tư, chuẩn bị khởi nghĩa vũ trang là nhiệm vụ trung tâm, đi từ khởi nghĩa từng phần tiến lên tổng khởi nghĩa."},{"s":112.86,"e":118.79,"c":2,"t":"Chuỗi Trung ương 6, 7, 8 là ví dụ điển hình về điều chỉnh chiến lược dựa trên mâu thuẫn chủ yếu."},{"s":118.9,"e":121.62,"c":3,"t":"Chuẩn bị lực lượng và cao trào kháng Nhật."},{"s":121.68,"e":126.22,"c":3,"t":"Mặt trận Việt Minh phát triển rộng khắp, căn cứ địa Việt Bắc được mở rộng."},{"s":126.17,"e":135.33,"c":3,"t":"Ngày 22 tháng 12 năm 1944, Đội Việt Nam Tuyên truyền Giải phóng quân ra đời do đồng chí Võ Nguyên Giáp chỉ huy, hạt nhân của Quân đội nhân dân Việt Nam."},{"s":135.44,"e":140.02,"c":3,"t":"Đêm 9 tháng 3 năm 1945, Nhật đảo chính Pháp."},{"s":139.97,"e":151.72,"c":3,"t":"Ngày 12 tháng 3, Ban Thường vụ Trung ương ra Chỉ thị Nhật, Pháp bắn nhau và hành động của chúng ta, xác định phát xít Nhật là kẻ thù chính trước mắt, phát động cao trào kháng Nhật cứu nước, chuyển cách mạng sang thời kỳ tiền khởi nghĩa."},{"s":151.72,"e":156.95,"c":3,"t":"Phong trào phá kho thóc cứu đói lan rộng, giữa lúc nạn đói làm khoảng hai triệu đồng bào chết đói."},{"s":157.06,"e":160.1,"c":4,"t":"Chớp thời cơ: Tổng khởi nghĩa Tháng Tám."},{"s":160.16,"e":164.5,"c":4,"t":"Giữa tháng 8 năm 1945, Nhật đầu hàng Đồng minh."},{"s":164.45,"e":170.43,"c":4,"t":"Bộ máy thống trị cũ tan rã, quân Đồng minh chưa kịp vào Đông Dương, phong trào cách mạng đã phát triển rộng."},{"s":170.43,"e":172.85,"c":4,"t":"Đây là thời cơ ngàn năm có một."},{"s":172.95,"e":178.53,"c":4,"t":"Hội nghị toàn quốc của Đảng ở Tân Trào từ ngày 13 đến 15 tháng 8 quyết định Tổng khởi nghĩa."},{"s":178.48,"e":184.88,"c":4,"t":"Quốc dân Đại hội Tân Trào ngày 16 tháng 8 tán thành, lập Ủy ban Dân tộc giải phóng do Hồ Chí Minh làm Chủ tịch."},{"s":184.88,"e":189.74,"c":4,"t":"Người kêu gọi: toàn quốc đồng bào hãy đứng dậy đem sức ta mà tự giải phóng cho ta."},{"s":189.84,"e":196.86,"c":4,"t":"Ngày 19 tháng 8 giành chính quyền ở Hà Nội, ngày 23 tháng 8 ở Huế, ngày 25 tháng 8 ở Sài Gòn."},{"s":196.81,"e":200.16,"c":4,"t":"Ngày 30 tháng 8, vua Bảo Đại thoái vị."},{"s":200.16,"e":204.52,"c":4,"t":"Đến cuối tháng 8, chính quyền cách mạng cơ bản được thiết lập trong cả nước."},{"s":204.63,"e":206.36,"c":5,"t":"Tuyên ngôn Độc lập."},{"s":206.5,"e":215.06,"c":5,"t":"Ngày 2 tháng 9 năm 1945, tại Quảng trường Ba Đình, Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa."},{"s":215.01,"e":224.82,"c":5,"t":"Tuyên ngôn mở đầu bằng quyền con người trong Tuyên ngôn Độc lập của Mỹ và Tuyên ngôn Nhân quyền và Dân quyền của Pháp, rồi nâng lên thành quyền dân tộc: tất cả các dân tộc trên thế giới đều sinh ra bình đẳng."},{"s":224.93,"e":239.31,"c":5,"t":"Tuyên ngôn tố cáo tội ác của thực dân Pháp, khẳng định nhân dân ta giành chính quyền từ tay Nhật chứ không phải từ tay Pháp, bác bỏ cơ sở pháp lý cho việc tái lập chế độ thuộc địa, và kết thúc: nước Việt Nam có quyền hưởng tự do và độc lập, và sự thật đã thành một nước tự do, độc lập."},{"s":239.36,"e":242.13,"c":6,"t":"Kết luận: nguyên nhân và ý nghĩa."},{"s":242.19,"e":246.64,"c":6,"t":"Về khách quan, chiến thắng của Liên Xô và Đồng minh trước phát xít tạo thời cơ."},{"s":246.59,"e":256.69,"c":6,"t":"Nhưng quyết định là nguyên nhân chủ quan: đường lối đúng với sự chuyển hướng kịp thời, quá trình chuẩn bị lâu dài qua các cao trào, khối đoàn kết toàn dân trong Mặt trận Việt Minh, và nghệ thuật chớp thời cơ."},{"s":256.8,"e":266.72,"c":6,"t":"Thắng lợi đập tan ách thống trị thực dân hơn tám mươi năm và chế độ quân chủ, đưa nhân dân từ thân phận nô lệ thành người làm chủ, mở ra kỷ nguyên độc lập dân tộc gắn liền với chủ nghĩa xã hội."},{"s":266.67,"e":270.9,"c":6,"t":"Bài học: chuẩn bị lâu dài phải đi cùng khả năng chớp thời cơ rất ngắn."}]},"1945-1954":{"duration":288.4,"chapters":[{"title":"Mở đầu: ngàn cân treo sợi tóc","target":"hero","start":0.0},{"title":"Bối cảnh: thù trong, giặc ngoài","target":"context","start":14.66},{"title":"Kháng chiến kiến quốc: giữ vững chính quyền","target":"dossiers","start":41.54},{"title":"Toàn quốc kháng chiến và đường lối kháng chiến","target":"expert","start":106.03},{"title":"Đại hội lần thứ hai của Đảng","target":"congress","start":165.74},{"title":"Điện Biên Phủ và Hiệp định Giơ ne vơ","target":"movements","start":207.26},{"title":"Kết luận: nguyên nhân thắng lợi và bài học","target":"results","start":257.3}],"cues":[{"s":0.1,"e":3.7,"c":0,"t":"Giành chính quyền đã khó, giữ chính quyền còn khó hơn."},{"s":3.65,"e":8.8,"c":0,"t":"Ngay sau ngày độc lập, nước Việt Nam Dân chủ Cộng hòa rơi vào tình thế ngàn cân treo sợi tóc."},{"s":8.8,"e":14.64,"c":0,"t":"Nhiệm vụ chuyển rất nhanh từ giành chính quyền sang giữ chính quyền, xây dựng chế độ mới và chuẩn bị kháng chiến."},{"s":14.76,"e":17.85,"c":1,"t":"Bối cảnh: thù trong, giặc ngoài."},{"s":17.91,"e":21.97,"c":1,"t":"Ở miền Bắc, gần hai mươi vạn quân Tưởng kéo vào cùng bọn tay sai."},{"s":21.92,"e":31.48,"c":1,"t":"Ở miền Nam, quân Anh mở đường cho Pháp quay lại; ngày 23 tháng 9 năm 1945, Pháp nổ súng đánh chiếm Sài Gòn, nhân dân Nam Bộ đứng lên kháng chiến."},{"s":31.59,"e":37.79,"c":1,"t":"Bên trong, nạn đói vừa qua, hơn chín mươi phần trăm dân số mù chữ, ngân khố gần như trống rỗng."},{"s":37.74,"e":41.53,"c":1,"t":"Giặc đói, giặc dốt và giặc ngoại xâm cùng lúc đe dọa."},{"s":41.64,"e":44.79,"c":2,"t":"Kháng chiến kiến quốc: giữ vững chính quyền."},{"s":44.86,"e":57.26,"c":2,"t":"Ngày 3 tháng 9 năm 1945, Chủ tịch Hồ Chí Minh nêu sáu nhiệm vụ cấp bách: chống đói, chống dốt, tổng tuyển cử, giáo dục tinh thần, bỏ thuế vô lý, tự do tín ngưỡng và đoàn kết lương giáo."},{"s":57.21,"e":69.52,"c":2,"t":"Ngày 25 tháng 11, Trung ương ra Chỉ thị Kháng chiến kiến quốc, xác định kẻ thù chính là thực dân Pháp xâm lược, với bốn nhiệm vụ: củng cố chính quyền, chống thực dân Pháp, bài trừ nội phản, cải thiện đời sống nhân dân."},{"s":69.63,"e":78.89,"c":2,"t":"Ngày 6 tháng 1 năm 1946, Tổng tuyển cử bầu Quốc hội đầu tiên; ngày 9 tháng 11 năm 1946, Hiến pháp đầu tiên được thông qua."},{"s":78.84,"e":86.9,"c":2,"t":"Phong trào tăng gia sản xuất, hũ gạo cứu đói, Bình dân học vụ, Quỹ Độc lập, Tuần lễ Vàng lan khắp cả nước, tiền Việt Nam được phát hành."},{"s":87.0,"e":91.46,"c":2,"t":"Về đối ngoại, ta hòa hoãn với Tưởng để tập trung chống Pháp ở miền Nam."},{"s":91.41,"e":102.22,"c":2,"t":"Khi Pháp và Tưởng bắt tay nhau, ta ký Hiệp định Sơ bộ ngày 6 tháng 3 và Tạm ước ngày 14 tháng 9 năm 1946 với Pháp, đẩy quân Tưởng về nước, kéo dài hòa bình để củng cố lực lượng."},{"s":102.22,"e":106.03,"c":2,"t":"Nguyên tắc: kiên định mục tiêu độc lập nhưng linh hoạt về sách lược."},{"s":106.13,"e":109.08,"c":3,"t":"Toàn quốc kháng chiến và đường lối kháng chiến."},{"s":109.13,"e":111.64,"c":3,"t":"Thực dân Pháp liên tiếp gây hấn."},{"s":111.59,"e":123.16,"c":3,"t":"Tối 19 tháng 12 năm 1946, cả nước bước vào kháng chiến với Lời kêu gọi của Chủ tịch Hồ Chí Minh: chúng ta thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ."},{"s":123.27,"e":135.35,"c":3,"t":"Lời kêu gọi, Chỉ thị Toàn dân kháng chiến và tác phẩm Kháng chiến nhất định thắng lợi của Tổng Bí thư Trường Chinh tạo thành đường lối kháng chiến: toàn dân, toàn diện, trường kỳ, dựa vào sức mình là chính và tranh thủ ủng hộ quốc tế."},{"s":135.3,"e":138.59,"c":3,"t":"Toàn dân, vì mỗi người dân là một chiến sĩ."},{"s":138.59,"e":144.84,"c":3,"t":"Toàn diện, vì đánh địch trên mọi mặt quân sự, chính trị, kinh tế, văn hóa, ngoại giao."},{"s":144.84,"e":148.68,"c":3,"t":"Trường kỳ, vì phải có thời gian chuyển hóa tương quan lực lượng."},{"s":148.78,"e":153.26,"c":3,"t":"Cuộc chiến đấu sáu mươi ngày đêm ở Hà Nội làm thất bại ý đồ đánh nhanh thắng nhanh."},{"s":153.21,"e":157.97,"c":3,"t":"Chiến thắng Việt Bắc thu đông năm 1947 bảo vệ cơ quan đầu não."},{"s":157.97,"e":165.74,"c":3,"t":"Chiến dịch Biên giới thu đông năm 1950 khai thông biên giới, phá thế bao vây, giúp ta giành thế chủ động chiến lược trên chiến trường chính."},{"s":165.84,"e":168.3,"c":4,"t":"Đại hội lần thứ hai của Đảng."},{"s":168.36,"e":180.77,"c":4,"t":"Tháng 2 năm 1951, Đại hội đại biểu toàn quốc lần thứ hai họp tại Chiêm Hóa, Tuyên Quang, đưa Đảng ra hoạt động công khai với tên Đảng Lao động Việt Nam; mỗi nước Việt Nam, Lào, Campuchia xây dựng đảng riêng phù hợp."},{"s":180.72,"e":183.73,"c":4,"t":"Đồng chí Trường Chinh được bầu làm Tổng Bí thư."},{"s":183.84,"e":189.94,"c":4,"t":"Chính cương xác định xã hội Việt Nam có ba tính chất: dân chủ nhân dân, một phần thuộc địa và nửa phong kiến."},{"s":189.89,"e":200.75,"c":4,"t":"Cách mạng Việt Nam là cách mạng dân tộc dân chủ nhân dân, do giai cấp công nhân lãnh đạo, nhiệm vụ đánh đuổi đế quốc, xóa bỏ tàn tích phong kiến, thực hiện người cày có ruộng, tiến tới chủ nghĩa xã hội."},{"s":200.75,"e":207.25,"c":4,"t":"Cải cách ruộng đất sau đó được đẩy mạnh để động viên nông dân, nhưng có sai lầm ở một số nơi và Đảng đã kiên quyết sửa sai."},{"s":207.36,"e":210.16,"c":5,"t":"Điện Biên Phủ và Hiệp định Giơ ne vơ."},{"s":210.22,"e":215.34,"c":5,"t":"Năm 1953, Pháp với sự giúp sức của Mỹ đưa ra kế hoạch Nava."},{"s":215.29,"e":226.44,"c":5,"t":"Bộ Chính trị mở cuộc tiến công Đông Xuân 1953 đến 1954, buộc địch phân tán lực lượng, rồi chọn Điện Biên Phủ, tập đoàn cứ điểm mạnh nhất Đông Dương, làm điểm quyết chiến chiến lược."},{"s":226.56,"e":231.49,"c":5,"t":"Đại tướng Võ Nguyên Giáp chuyển phương châm từ đánh nhanh giải quyết nhanh sang đánh chắc tiến chắc."},{"s":231.44,"e":242.73,"c":5,"t":"Từ ngày 13 tháng 3 đến 7 tháng 5 năm 1954, qua ba đợt tiến công, sau năm mươi sáu ngày đêm khoét núi, ngủ hầm, mưa dầm, cơm vắt, toàn bộ tập đoàn cứ điểm bị tiêu diệt."},{"s":242.84,"e":252.81,"c":5,"t":"Ngày 21 tháng 7 năm 1954, Hiệp định Giơ ne vơ được ký, các nước cam kết tôn trọng độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ ba nước Đông Dương."},{"s":252.76,"e":257.29,"c":5,"t":"Miền Bắc hoàn toàn giải phóng, đất nước tạm thời bị chia cắt về quân sự."},{"s":257.4,"e":260.4,"c":6,"t":"Kết luận: nguyên nhân thắng lợi và bài học."},{"s":260.45,"e":274.84,"c":6,"t":"Năm nguyên nhân thắng lợi: đường lối chiến tranh nhân dân đúng đắn của Đảng; khối đoàn kết toàn dân trong mặt trận dân tộc thống nhất; lực lượng vũ trang ngày càng lớn mạnh; chính quyền dân chủ nhân dân được giữ vững; liên minh Việt, Lào, Campuchia cùng sự ủng hộ quốc tế."},{"s":274.9,"e":278.79,"c":6,"t":"Lần đầu tiên một nước thuộc địa nhỏ đánh thắng một cường quốc thực dân."},{"s":278.74,"e":288.36,"c":6,"t":"Bài học: giữ chính quyền đòi hỏi xác định đúng kẻ thù chính, tận dụng hòa hoãn để chuẩn bị lực lượng, và kết hợp chính trị, kinh tế, quân sự, ngoại giao ngay từ đầu."}]},"1954-1975":{"duration":274.8,"chapters":[{"title":"Mở đầu: một nước, hai miền, hai nhiệm vụ","target":"hero","start":0.0},{"title":"Bối cảnh: Mỹ thay chân Pháp","target":"context","start":13.73},{"title":"Nghị quyết 15 và phong trào Đồng Khởi","target":"dossiers","start":42.0},{"title":"Đại hội lần thứ ba: đường lối hai chiến lược","target":"congress","start":76.78},{"title":"Đánh bại từng chiến lược chiến tranh của Mỹ","target":"expert","start":111.36},{"title":"Đại thắng mùa Xuân 1975","target":"movements","start":190.44},{"title":"Kết luận: mốc son chói lọi nhất","target":"results","start":238.39}],"cues":[{"s":0.1,"e":3.8,"c":0,"t":"Sau Hiệp định Giơ ne vơ, đất nước tạm thời chia cắt."},{"s":3.75,"e":9.64,"c":0,"t":"Làm sao vừa xây dựng chủ nghĩa xã hội ở miền Bắc, vừa giải phóng miền Nam trước đế quốc giàu mạnh nhất thế giới?"},{"s":9.64,"e":13.72,"c":0,"t":"Hai mươi mốt năm tiếp theo là câu trả lời đầy bản lĩnh của cả dân tộc."},{"s":13.83,"e":16.46,"c":1,"t":"Bối cảnh: Mỹ thay chân Pháp."},{"s":16.52,"e":22.6,"c":1,"t":"Miền Bắc được giải phóng, bước vào khôi phục kinh tế, cải tạo xã hội chủ nghĩa, xây dựng hậu phương."},{"s":22.55,"e":28.78,"c":1,"t":"Ở miền Nam, Mỹ dựng chính quyền Ngô Đình Diệm, phá hoại hiệp thương tổng tuyển cử, âm mưu chia cắt lâu dài."},{"s":28.9,"e":32.46,"c":1,"t":"Chính quyền Diệm thi hành chính sách tố cộng, diệt cộng."},{"s":32.41,"e":42.0,"c":1,"t":"Những năm đầu, Đảng chủ trương đấu tranh chính trị, giữ gìn lực lượng; nhưng đến 1957, 1958, cách mạng miền Nam tổn thất nặng nề."},{"s":42.1,"e":45.02,"c":2,"t":"Nghị quyết 15 và phong trào Đồng Khởi."},{"s":45.08,"e":58.21,"c":2,"t":"Tháng 1 năm 1959, Hội nghị Trung ương 15 khóa hai xác định con đường cơ bản của cách mạng miền Nam là dùng bạo lực cách mạng, khởi nghĩa giành chính quyền về tay nhân dân, từ đấu tranh chính trị tiến lên kết hợp đấu tranh chính trị với đấu tranh vũ trang."},{"s":58.28,"e":67.03,"c":2,"t":"Phong trào Đồng Khởi bùng nổ, tiêu biểu ở Bến Tre từ ngày 17 tháng 1 năm 1960, với đội quân tóc dài nổi tiếng, rồi lan rộng khắp miền Nam."},{"s":66.98,"e":72.81,"c":2,"t":"Ngày 20 tháng 12 năm 1960, Mặt trận Dân tộc Giải phóng miền Nam Việt Nam ra đời."},{"s":72.81,"e":76.78,"c":2,"t":"Cách mạng miền Nam chuyển từ thế giữ gìn lực lượng sang thế tiến công."},{"s":76.88,"e":80.13,"c":3,"t":"Đại hội lần thứ ba: đường lối hai chiến lược."},{"s":80.19,"e":92.01,"c":3,"t":"Tháng 9 năm 1960, Đại hội đại biểu toàn quốc lần thứ ba họp tại Hà Nội, đề ra đường lối tiến hành đồng thời hai chiến lược cách mạng: cách mạng xã hội chủ nghĩa ở miền Bắc và cách mạng dân tộc dân chủ nhân dân ở miền Nam."},{"s":92.07,"e":102.14,"c":3,"t":"Điểm phải phân biệt rõ: cách mạng miền Bắc giữ vai trò quyết định nhất đối với toàn bộ cách mạng cả nước, vì là hậu phương lớn; cách mạng miền Nam giữ vai trò quyết định trực tiếp đối với giải phóng miền Nam."},{"s":102.09,"e":106.05,"c":3,"t":"Hai chiến lược gắn bó mật thiết, cùng hướng tới thống nhất nước nhà."},{"s":106.05,"e":111.36,"c":3,"t":"Chủ tịch Hồ Chí Minh tiếp tục là Chủ tịch Đảng, đồng chí Lê Duẩn được bầu làm Bí thư thứ nhất."},{"s":111.46,"e":114.4,"c":4,"t":"Đánh bại từng chiến lược chiến tranh của Mỹ."},{"s":114.46,"e":124.53,"c":4,"t":"Từ 1961 đến 1965 là chiến tranh đặc biệt, dùng quân đội Sài Gòn làm lực lượng chủ yếu với cố vấn, vũ khí Mỹ, xương sống là ấp chiến lược."},{"s":124.48,"e":131.18,"c":4,"t":"Chiến thắng Ấp Bắc năm 1963 và Bình Giã cuối năm 1964 làm chiến lược này phá sản."},{"s":131.28,"e":138.08,"c":4,"t":"Từ năm 1965, Mỹ đưa quân viễn chinh vào, tiến hành chiến tranh cục bộ, đồng thời ném bom miền Bắc."},{"s":138.03,"e":144.83,"c":4,"t":"Hội nghị Trung ương 11 và 12 năm 1965 nêu quyết tâm đánh thắng giặc Mỹ trong bất cứ tình huống nào."},{"s":144.83,"e":151.81,"c":4,"t":"Miền Bắc vừa sản xuất, vừa chiến đấu, vừa chi viện miền Nam; Vạn Tường và hai mùa khô làm suy giảm ưu thế quân Mỹ."},{"s":151.81,"e":156.75,"c":4,"t":"Chủ tịch Hồ Chí Minh khẳng định chân lý: không có gì quý hơn độc lập, tự do."},{"s":156.87,"e":168.47,"c":4,"t":"Tết Mậu Thân năm 1968, Tổng tiến công và nổi dậy làm lung lay ý chí xâm lược của Mỹ, buộc Mỹ xuống thang và đàm phán ở Pa ri; đồng thời lực lượng ta cũng chịu tổn thất lớn, cần đánh giá cân bằng."},{"s":168.42,"e":173.02,"c":4,"t":"Từ năm 1969, Mỹ chuyển sang Việt Nam hóa chiến tranh."},{"s":173.02,"e":180.76,"c":4,"t":"Cuối năm 1972, quân dân miền Bắc đánh bại cuộc tập kích bằng B năm mươi hai suốt mười hai ngày đêm, làm nên Điện Biên Phủ trên không."},{"s":180.76,"e":190.43,"c":4,"t":"Ngày 27 tháng 1 năm 1973, Hiệp định Pa ri được ký, Mỹ cam kết tôn trọng độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ Việt Nam và rút quân."},{"s":190.54,"e":193.75,"c":5,"t":"Đại thắng mùa Xuân 1975."},{"s":193.8,"e":198.23,"c":5,"t":"Sau Hiệp định Pa ri, Trung ương xác định tiếp tục giữ vững thế tiến công."},{"s":198.18,"e":208.31,"c":5,"t":"Bộ Chính trị đề ra kế hoạch giải phóng miền Nam trong hai năm 1975 và 1976, nhưng nhấn mạnh nếu thời cơ đến thì giải phóng ngay trong năm 1975."},{"s":208.31,"e":212.75,"c":5,"t":"Chiến thắng Phước Long đầu năm 1975 là phép thử chiến lược."},{"s":212.86,"e":218.69,"c":5,"t":"Ngày 10 tháng 3, trận Buôn Ma Thuột mở màn Chiến dịch Tây Nguyên, hệ thống phòng thủ địch tan rã nhanh."},{"s":218.64,"e":227.83,"c":5,"t":"Tiếp đó là chiến dịch Huế, Đà Nẵng, rồi Chiến dịch Hồ Chí Minh từ 26 đến 30 tháng 4 với tinh thần thần tốc, táo bạo, bất ngờ, chắc thắng."},{"s":227.83,"e":234.96,"c":5,"t":"11 giờ 30 phút ngày 30 tháng 4 năm 1975, Dinh Độc Lập bị chiếm, chính quyền Sài Gòn đầu hàng."},{"s":234.96,"e":238.38,"c":5,"t":"Miền Nam hoàn toàn giải phóng, đất nước thống nhất."},{"s":238.49,"e":241.26,"c":6,"t":"Kết luận: mốc son chói lọi nhất."},{"s":241.32,"e":249.58,"c":6,"t":"Thắng lợi kết thúc hai mươi mốt năm chống Mỹ, ba mươi năm chiến tranh giải phóng, mở ra kỷ nguyên cả nước độc lập, thống nhất, đi lên chủ nghĩa xã hội."},{"s":249.53,"e":262.94,"c":6,"t":"Nguyên nhân: đường lối độc lập, tự chủ, sáng tạo của Đảng; sự kết hợp hai miền và ba mặt trận quân sự, chính trị, ngoại giao; hậu phương lớn miền Bắc; sức mạnh đại đoàn kết dân tộc, liên minh ba nước Đông Dương và sự ủng hộ quốc tế."},{"s":263.04,"e":269.93,"c":6,"t":"Bài học: kết hợp sức mạnh dân tộc với sức mạnh thời đại; nghệ thuật chiến lược nằm ở đánh giá đúng thời cơ và tương quan lực lượng."},{"s":269.88,"e":274.75,"c":6,"t":"Năm 1975 là mẫu mực về nắm thời cơ và chỉ đạo chiến lược."}]},"1975-1986":{"duration":220.9,"chapters":[{"title":"Mở đầu: thắng giặc rồi, xây dựng thế nào?","target":"hero","start":0.0},{"title":"Bối cảnh: hậu quả chiến tranh và cơ chế cũ","target":"context","start":15.67},{"title":"Thống nhất nhà nước và Đại hội lần thứ tư","target":"congress","start":48.34},{"title":"Bảo vệ Tổ quốc ở hai đầu biên giới","target":"expert","start":94.56},{"title":"Những bước tìm tòi đổi mới","target":"dossiers","start":128.45},{"title":"Kết luận: bài học từ khủng hoảng","target":"results","start":189.65}],"cues":[{"s":0.1,"e":7.08,"c":0,"t":"Sau mùa Xuân 1975, câu hỏi đặt ra là: xây dựng một đất nước nghèo, vừa ra khỏi chiến tranh như thế nào?"},{"s":7.03,"e":15.65,"c":0,"t":"Mười năm 1975 đến 1986 là mười năm vừa xây dựng, vừa bảo vệ Tổ quốc, vừa vấp ngã và tự tìm ra con đường đúng."},{"s":15.77,"e":19.21,"c":1,"t":"Bối cảnh: hậu quả chiến tranh và cơ chế cũ."},{"s":19.28,"e":25.39,"c":1,"t":"Hậu quả chiến tranh rất nặng nề: hàng triệu người chết và bị thương, ruộng đồng, cầu cống bị tàn phá."},{"s":25.34,"e":29.04,"c":1,"t":"Mỹ thi hành cấm vận, viện trợ bên ngoài giảm dần."},{"s":29.14,"e":34.79,"c":1,"t":"Cả nước áp dụng cơ chế kế hoạch hóa tập trung, quan liêu, bao cấp vốn phù hợp thời chiến."},{"s":34.74,"e":48.33,"c":1,"t":"Trong thời bình, cơ chế ấy bộc lộ hạn chế: giá cả, tiền lương, phân phối vật tư do mệnh lệnh hành chính; doanh nghiệp thiếu quyền tự chủ; người làm nhiều cũng như người làm ít; cơ chế xin cho; hàng hóa khan hiếm, phân phối bằng tem phiếu."},{"s":48.44,"e":51.35,"c":2,"t":"Thống nhất nhà nước và Đại hội lần thứ tư."},{"s":51.41,"e":56.72,"c":2,"t":"Ngày 25 tháng 4 năm 1976, Tổng tuyển cử bầu Quốc hội chung."},{"s":56.67,"e":65.85,"c":2,"t":"Ngày 2 tháng 7 năm 1976, Quốc hội đặt tên nước Cộng hòa xã hội chủ nghĩa Việt Nam, thủ đô Hà Nội, thống nhất hệ thống nhà nước và các biểu tượng quốc gia."},{"s":65.96,"e":85.1,"c":2,"t":"Tháng 12 năm 1976, Đại hội đại biểu toàn quốc lần thứ tư đổi tên Đảng thành Đảng Cộng sản Việt Nam, bầu đồng chí Lê Duẩn làm Tổng Bí thư, đề ra đường lối cả nước đi lên chủ nghĩa xã hội, tiến hành đồng thời ba cuộc cách mạng về quan hệ sản xuất, khoa học kỹ thuật và tư tưởng văn hóa, trong đó cách mạng khoa học kỹ thuật là then chốt, đẩy mạnh công nghiệp hóa xã hội chủ nghĩa."},{"s":85.16,"e":94.59,"c":2,"t":"Hạn chế cần nhớ: đường lối còn chủ quan, nóng vội, muốn tiến nhanh lên sản xuất lớn, ưu tiên công nghiệp nặng khi nguồn lực còn rất hạn chế, kéo dài cơ chế bao cấp."},{"s":94.66,"e":97.5,"c":3,"t":"Bảo vệ Tổ quốc ở hai đầu biên giới."},{"s":97.56,"e":101.5,"c":3,"t":"Ở biên giới Tây Nam, tập đoàn Pôn Pốt liên tục tấn công."},{"s":101.45,"e":110.08,"c":3,"t":"Quân dân ta phản công, cùng lực lượng cách mạng Campuchia giải phóng Phnôm Pênh ngày 7 tháng 1 năm 1979, cứu nhân dân Campuchia khỏi diệt chủng."},{"s":110.08,"e":117.92,"c":3,"t":"Ngày 17 tháng 2 năm 1979, chiến tranh bảo vệ biên giới phía Bắc nổ ra; quân dân ta chiến đấu kiên cường bảo vệ chủ quyền."},{"s":118.04,"e":122.77,"c":3,"t":"Chiến tranh và cấm vận làm tăng chi phí quốc phòng, nền kinh tế càng kiệt quệ."},{"s":122.72,"e":128.44,"c":3,"t":"Nhưng lưu ý: yếu tố khách quan không thay thế việc nhìn nhận những hạn chế chủ quan trong quản lý kinh tế."},{"s":128.55,"e":130.84,"c":4,"t":"Những bước tìm tòi đổi mới."},{"s":130.9,"e":143.69,"c":4,"t":"Hội nghị Trung ương 6 khóa bốn, họp tháng 8 năm 1979, nghị quyết ban hành tháng 9, chủ trương làm cho sản xuất bung ra, kết hợp kế hoạch với thị trường ở mức nhất định, kết hợp lợi ích Nhà nước, tập thể và cá nhân."},{"s":143.64,"e":147.79,"c":4,"t":"Đây chưa phải đổi mới toàn diện nhưng là bước mở đầu tìm tòi đổi mới."},{"s":147.89,"e":155.29,"c":4,"t":"Tháng 1 năm 1981, Ban Bí thư ra Chỉ thị 100 về khoán sản phẩm đến nhóm và người lao động trong hợp tác xã nông nghiệp."},{"s":155.24,"e":160.78,"c":4,"t":"Người nông dân được hưởng phần vượt khoán, sản lượng tăng rõ rệt, tạo kinh nghiệm cho khoán mười sau này."},{"s":160.9,"e":171.63,"c":4,"t":"Tháng 3 năm 1982, Đại hội lần thứ năm nhận thức thời kỳ quá độ là lâu dài, coi nông nghiệp là mặt trận hàng đầu, chú trọng hàng tiêu dùng và xuất khẩu, nhưng chưa đổi căn bản cơ chế."},{"s":171.58,"e":178.65,"c":4,"t":"Tháng 6 năm 1985, Hội nghị Trung ương 8 khóa năm chủ trương xóa bao cấp trong giá, lương, tiền."},{"s":178.65,"e":189.65,"c":4,"t":"Do thiếu đồng bộ, chưa kiểm soát bội chi và tiền tệ, cuộc tổng điều chỉnh tháng 9 năm 1985 thất bại, đẩy lạm phát năm 1986 lên khoảng bảy trăm bảy mươi tư phẩy bảy phần trăm."},{"s":189.75,"e":192.57,"c":5,"t":"Kết luận: bài học từ khủng hoảng."},{"s":192.63,"e":197.12,"c":5,"t":"Đến giữa thập niên tám mươi, đất nước khủng hoảng kinh tế xã hội trầm trọng."},{"s":197.07,"e":199.95,"c":5,"t":"Chính khủng hoảng buộc Đảng nhìn thẳng vào sự thật."},{"s":199.95,"e":206.98,"c":5,"t":"Từ khoán một trăm đến giá, lương, tiền là quá trình tích lũy nhận thức, chuẩn bị trực tiếp cho bước ngoặt Đại hội lần thứ sáu."},{"s":207.08,"e":220.96,"c":5,"t":"Bài học: đường lối phát triển phải xuất phát từ thực tế và trình độ lực lượng sản xuất; cải cách không thể chỉ thay đổi giá hay tiền tệ mà phải đồng bộ thể chế, doanh nghiệp, tài chính và chính sách xã hội; đổi mới lớn thường bắt đầu từ sáng kiến của cơ sở, của nhân dân."}]},"1986-2001":{"duration":219.7,"chapters":[{"title":"Mở đầu: đổi mới hay là chết","target":"hero","start":0.0},{"title":"Bối cảnh: thế giới chuyển động, đất nước khủng hoảng","target":"context","start":14.66},{"title":"Đại hội lần thứ sáu: bước ngoặt Đổi mới","target":"congress","start":33.29},{"title":"Đổi mới đi vào cuộc sống","target":"dossiers","start":80.64},{"title":"Cương lĩnh 1991 và những bước tiến đối ngoại","target":"expert","start":127.08},{"title":"Đại hội lần thứ tám: đẩy mạnh công nghiệp hóa","target":"results","start":178.97}],"cues":[{"s":0.1,"e":4.1,"c":0,"t":"Có một câu nói rất nổi tiếng ở thời điểm này: đổi mới hay là chết."},{"s":4.05,"e":10.7,"c":0,"t":"Năm 1986, lạm phát hàng trăm phần trăm, hàng hóa khan hiếm, đời sống vô cùng khó khăn."},{"s":10.7,"e":14.64,"c":0,"t":"Trong hoàn cảnh ấy, Đảng đưa ra một quyết định mang tầm lịch sử."},{"s":14.76,"e":18.58,"c":1,"t":"Bối cảnh: thế giới chuyển động, đất nước khủng hoảng."},{"s":18.65,"e":23.19,"c":1,"t":"Cách mạng khoa học công nghệ phát triển mạnh, xu thế đối thoại thay đối đầu xuất hiện."},{"s":23.14,"e":27.24,"c":1,"t":"Liên Xô và các nước xã hội chủ nghĩa tiến hành cải tổ, cải cách."},{"s":27.24,"e":30.91,"c":1,"t":"Trong nước, khủng hoảng kinh tế xã hội lên đến đỉnh điểm."},{"s":30.91,"e":33.28,"c":1,"t":"Không thể làm như cũ được nữa."},{"s":33.39,"e":36.64,"c":2,"t":"Đại hội lần thứ sáu: bước ngoặt Đổi mới."},{"s":36.7,"e":53.54,"c":2,"t":"Tháng 12 năm 1986, Đại hội đại biểu toàn quốc lần thứ sáu với tinh thần nhìn thẳng vào sự thật, đánh giá đúng sự thật, nói rõ sự thật, đã tự phê bình nghiêm túc, chỉ ra sai lầm chủ quan, duy ý chí trong bố trí cơ cấu kinh tế, cải tạo xã hội chủ nghĩa, cơ chế quản lý và phân phối lưu thông."},{"s":53.49,"e":56.66,"c":2,"t":"Đồng chí Nguyễn Văn Linh được bầu làm Tổng Bí thư."},{"s":56.76,"e":72.71,"c":2,"t":"Đại hội đề ra đường lối đổi mới toàn diện, trước hết là đổi mới tư duy kinh tế: phát triển kinh tế hàng hóa nhiều thành phần; xóa bỏ cơ chế tập trung quan liêu bao cấp, chuyển sang hạch toán kinh doanh; thực hiện ba chương trình kinh tế lớn là lương thực thực phẩm, hàng tiêu dùng và hàng xuất khẩu; mở rộng kinh tế đối ngoại."},{"s":72.77,"e":80.68,"c":2,"t":"Điều rất quan trọng: đổi mới không thay đổi mục tiêu chủ nghĩa xã hội, mà đổi phương thức, cơ chế và bước đi để thực hiện mục tiêu ấy hiệu quả hơn."},{"s":80.74,"e":82.89,"c":3,"t":"Đổi mới đi vào cuộc sống."},{"s":82.95,"e":88.23,"c":3,"t":"Năm 1987, Luật Đầu tư nước ngoài mở kênh huy động vốn và công nghệ."},{"s":88.18,"e":95.85,"c":3,"t":"Tháng 4 năm 1988, Bộ Chính trị ra Nghị quyết 10, khoán mười, thừa nhận hộ nông dân là đơn vị kinh tế tự chủ."},{"s":95.85,"e":102.61,"c":3,"t":"Năm 1989, từ một nước thiếu lương thực, Việt Nam bắt đầu xuất khẩu gạo, lạm phát từng bước giảm."},{"s":102.61,"e":108.99,"c":3,"t":"Cũng năm 1989, Việt Nam hoàn thành rút quân tình nguyện khỏi Campuchia, mở đường phá thế bao vây."},{"s":109.08,"e":127.12,"c":3,"t":"Tháng 3 năm 1989, Hội nghị Trung ương 6 khóa sáu nêu năm nguyên tắc để đổi mới không chệch hướng: đi lên chủ nghĩa xã hội là con đường tất yếu; chủ nghĩa Mác Lênin là nền tảng tư tưởng; đổi mới hệ thống chính trị để tăng cường vai trò lãnh đạo của Đảng; xây dựng dân chủ xã hội chủ nghĩa; kết hợp chủ nghĩa yêu nước với chủ nghĩa quốc tế."},{"s":127.18,"e":131.27,"c":4,"t":"Cương lĩnh 1991 và những bước tiến đối ngoại."},{"s":131.33,"e":144.2,"c":4,"t":"Tháng 6 năm 1991, giữa lúc Liên Xô và Đông Âu khủng hoảng sâu sắc, Đại hội lần thứ bảy thông qua Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội, với sáu đặc trưng của xã hội xã hội chủ nghĩa và các phương hướng cơ bản."},{"s":144.15,"e":151.04,"c":4,"t":"Lần đầu tiên Đảng khẳng định lấy chủ nghĩa Mác Lênin và tư tưởng Hồ Chí Minh làm nền tảng tư tưởng, kim chỉ nam cho hành động."},{"s":151.04,"e":154.03,"c":4,"t":"Đồng chí Đỗ Mười được bầu làm Tổng Bí thư."},{"s":154.13,"e":160.14,"c":4,"t":"Về đối ngoại, Việt Nam muốn là bạn với tất cả các nước, chuyển sang đa dạng hóa, đa phương hóa."},{"s":160.09,"e":168.4,"c":4,"t":"Năm 1991 bình thường hóa quan hệ với Trung Quốc; tháng 7 năm 1995 bình thường hóa quan hệ với Hoa Kỳ và gia nhập ASEAN."},{"s":168.4,"e":178.97,"c":4,"t":"Tháng 1 năm 1994, Hội nghị giữa nhiệm kỳ cảnh báo bốn nguy cơ: tụt hậu xa hơn về kinh tế, chệch hướng xã hội chủ nghĩa, tham nhũng và tệ quan liêu, diễn biến hòa bình."},{"s":179.07,"e":182.49,"c":5,"t":"Đại hội lần thứ tám: đẩy mạnh công nghiệp hóa."},{"s":182.55,"e":197.71,"c":5,"t":"Tháng 6 năm 1996, Đại hội lần thứ tám đánh giá nước ta đã ra khỏi khủng hoảng kinh tế xã hội, nhiệm vụ chuẩn bị tiền đề cho công nghiệp hóa cơ bản hoàn thành, chuyển sang thời kỳ đẩy mạnh công nghiệp hóa, hiện đại hóa, phấn đấu đến năm 2020 cơ bản thành nước công nghiệp."},{"s":197.66,"e":203.34,"c":5,"t":"Khủng hoảng tài chính châu Á 1997 làm tăng khó khăn nhưng không đảo ngược đổi mới."},{"s":203.45,"e":219.77,"c":5,"t":"Bài học sau mười năm đổi mới: kiên định mục tiêu độc lập dân tộc và chủ nghĩa xã hội; đổi mới toàn diện nhưng có trọng tâm, kết hợp đổi mới kinh tế với đổi mới chính trị phù hợp; phát triển nhiều thành phần kinh tế đi đôi với vai trò quản lý của Nhà nước; xây dựng Đảng là then chốt; và tổng kết thực tiễn là nguồn gốc phát triển lý luận."}]},"2001-2011":{"duration":145.9,"chapters":[{"title":"Mở đầu: bước vào thế kỷ mới","target":"hero","start":0.0},{"title":"Bối cảnh: toàn cầu hóa và cạnh tranh","target":"context","start":12.24},{"title":"Đại hội lần thứ chín và lần thứ mười","target":"congress","start":31.39},{"title":"Gia nhập WTO: cơ hội và thử thách","target":"dossiers","start":76.97},{"title":"Kết luận: tăng trưởng phải đi cùng chất lượng","target":"results","start":114.36}],"cues":[{"s":0.1,"e":4.26,"c":0,"t":"Bước vào thế kỷ hai mươi mốt, Việt Nam đã có mười lăm năm Đổi mới."},{"s":4.21,"e":12.23,"c":0,"t":"Câu hỏi giờ đây không còn là có đổi mới hay không, mà là: mô hình kinh tế của chúng ta là gì, và hội nhập sâu vào thế giới thì được gì, mất gì?"},{"s":12.34,"e":15.43,"c":1,"t":"Bối cảnh: toàn cầu hóa và cạnh tranh."},{"s":15.48,"e":22.56,"c":1,"t":"Toàn cầu hóa kinh tế trở thành xu thế khách quan, cách mạng khoa học công nghệ, nhất là công nghệ thông tin, phát triển như vũ bão."},{"s":22.51,"e":26.06,"c":1,"t":"Các nước trong khu vực cạnh tranh gay gắt để thu hút đầu tư."},{"s":26.06,"e":31.38,"c":1,"t":"Trong nước, kinh tế tăng trưởng khá, nhưng năng suất, chất lượng và sức cạnh tranh còn thấp."},{"s":31.49,"e":34.27,"c":2,"t":"Đại hội lần thứ chín và lần thứ mười."},{"s":34.32,"e":40.05,"c":2,"t":"Tháng 4 năm 2001, Đại hội lần thứ chín bầu đồng chí Nông Đức Mạnh làm Tổng Bí thư."},{"s":40.0,"e":49.75,"c":2,"t":"Điểm nhấn lý luận: xác định kinh tế thị trường định hướng xã hội chủ nghĩa là mô hình kinh tế tổng quát của nước ta trong thời kỳ quá độ, phát huy nội lực đồng thời chủ động hội nhập kinh tế quốc tế."},{"s":49.85,"e":63.08,"c":2,"t":"Nghĩa là nền kinh tế vận hành theo quy luật thị trường, có nhiều hình thức sở hữu, nhiều thành phần kinh tế, nhưng có sự quản lý của Nhà nước pháp quyền xã hội chủ nghĩa do Đảng lãnh đạo, hướng tới dân giàu, nước mạnh, dân chủ, công bằng, văn minh."},{"s":63.15,"e":77.0,"c":2,"t":"Tháng 4 năm 2006, Đại hội lần thứ mười tiếp tục hoàn thiện thể chế kinh tế thị trường định hướng xã hội chủ nghĩa, chủ trương sớm đưa nước ta ra khỏi tình trạng kém phát triển, chủ động và tích cực hội nhập, đồng thời nhấn mạnh phòng chống tham nhũng, lãng phí."},{"s":77.07,"e":80.33,"c":3,"t":"Gia nhập WTO: cơ hội và thử thách."},{"s":80.38,"e":87.14,"c":3,"t":"Ngày 11 tháng 1 năm 2007, Việt Nam trở thành thành viên thứ một trăm năm mươi của Tổ chức Thương mại Thế giới."},{"s":87.09,"e":92.54,"c":3,"t":"Thị trường xuất khẩu mở rộng, vốn đầu tư nước ngoài đổ vào mạnh, cải cách pháp luật được thúc đẩy."},{"s":92.64,"e":101.3,"c":3,"t":"Cùng với cơ hội là thử thách: doanh nghiệp trong nước cạnh tranh gay gắt ngay trên sân nhà; thách thức về chất lượng tăng trưởng, chênh lệch phát triển, môi trường và quản trị."},{"s":101.25,"e":114.35,"c":3,"t":"Khủng hoảng tài chính toàn cầu cho thấy nền kinh tế đã gắn sâu với thế giới: lạm phát năm 2008 khoảng hai mươi ba phẩy mười hai phần trăm, năm 2011 khoảng mười tám phẩy sáu mươi tám phần trăm, buộc phải ưu tiên ổn định kinh tế vĩ mô."},{"s":114.46,"e":117.6,"c":4,"t":"Kết luận: tăng trưởng phải đi cùng chất lượng."},{"s":117.65,"e":127.94,"c":4,"t":"Thành tựu rõ nét: năm 2008, Việt Nam ra khỏi nhóm nước thu nhập thấp, trở thành nước thu nhập trung bình thấp; kinh tế tư nhân, xuất khẩu và công nghiệp chế biến mở rộng nhanh."},{"s":127.89,"e":133.59,"c":4,"t":"Nhưng tham nhũng, quan liêu, suy thoái đạo đức và hiệu lực quản lý trở thành thách thức ngày càng rõ."},{"s":133.68,"e":141.01,"c":4,"t":"Bài học: hội nhập phải đi cùng nâng cao nội lực, năng suất và sức chống chịu; tăng trưởng nhanh mà thiếu chất lượng sẽ tích tụ rủi ro."},{"s":140.96,"e":145.86,"c":4,"t":"Bài học ấy dẫn tới các đột phá chiến lược và công cuộc chỉnh đốn Đảng của thập niên tiếp theo."}]},"2011-2021":{"duration":180.2,"chapters":[{"title":"Mở đầu: chọn điểm then chốt để bứt phá","target":"hero","start":0.0},{"title":"Đại hội lần thứ mười một và Cương lĩnh 2011","target":"congress","start":13.97},{"title":"Ba đột phá chiến lược","target":"dossiers","start":64.63},{"title":"Xây dựng, chỉnh đốn Đảng","target":"expert","start":100.61},{"title":"Hội nhập thế hệ mới và thử thách đại dịch","target":"results","start":141.14}],"cues":[{"s":0.1,"e":5.52,"c":0,"t":"Khi nguồn lực có hạn mà việc phải làm rất nhiều, người lãnh đạo phải chọn đúng điểm then chốt để đột phá."},{"s":5.47,"e":13.96,"c":0,"t":"Thập niên 2011 đến 2021 là thập niên của những đột phá chiến lược, và cũng là thập niên Đảng đặc biệt chú trọng tự chỉnh đốn chính mình."},{"s":14.07,"e":17.92,"c":1,"t":"Đại hội lần thứ mười một và Cương lĩnh 2011."},{"s":17.98,"e":32.88,"c":1,"t":"Tháng 1 năm 2011, Đại hội lần thứ mười một bầu đồng chí Nguyễn Phú Trọng làm Tổng Bí thư, thông qua Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội, bổ sung, phát triển năm 2011, tổng kết hơn tám mươi năm cách mạng và hai mươi lăm năm đổi mới."},{"s":32.93,"e":41.68,"c":1,"t":"Cương lĩnh nêu tám đặc trưng của xã hội xã hội chủ nghĩa, mở đầu bằng mục tiêu tổng quát: dân giàu, nước mạnh, dân chủ, công bằng, văn minh."},{"s":41.63,"e":52.89,"c":1,"t":"So với sáu đặc trưng của Cương lĩnh 1991, có bổ sung quan trọng như Nhà nước pháp quyền xã hội chủ nghĩa của nhân dân, do nhân dân, vì nhân dân, và quan hệ hữu nghị, hợp tác với các nước."},{"s":52.89,"e":64.63,"c":1,"t":"Cương lĩnh xác định tám phương hướng lớn và các mối quan hệ lớn: đổi mới, ổn định và phát triển; kinh tế thị trường và định hướng xã hội chủ nghĩa; tăng trưởng và công bằng xã hội; độc lập tự chủ và hội nhập quốc tế."},{"s":64.73,"e":66.72,"c":2,"t":"Ba đột phá chiến lược."},{"s":66.77,"e":71.83,"c":2,"t":"Chiến lược 2011 đến 2020 xác định ba khâu đột phá."},{"s":71.78,"e":79.35,"c":2,"t":"Một là, hoàn thiện thể chế kinh tế thị trường định hướng xã hội chủ nghĩa, trọng tâm là môi trường cạnh tranh bình đẳng và cải cách hành chính."},{"s":79.35,"e":83.77,"c":2,"t":"Hai là, phát triển nhanh nguồn nhân lực, nhất là nhân lực chất lượng cao."},{"s":83.77,"e":87.28,"c":2,"t":"Ba là, xây dựng hệ thống kết cấu hạ tầng đồng bộ."},{"s":87.39,"e":93.53,"c":2,"t":"Thể chế đứng đầu vì được ví như điểm nghẽn của điểm nghẽn; ba đột phá như kiềng ba chân, nâng đỡ lẫn nhau."},{"s":93.48,"e":100.61,"c":2,"t":"Năm 2013, Hiến pháp mới được thông qua, tiếp tục khẳng định quyền con người, quyền công dân và Nhà nước pháp quyền."},{"s":100.71,"e":103.25,"c":3,"t":"Xây dựng, chỉnh đốn Đảng."},{"s":103.32,"e":112.68,"c":3,"t":"Tháng 1 năm 2016, Đại hội lần thứ mười hai nhìn lại ba mươi năm đổi mới, khẳng định đường lối đúng đắn, yêu cầu đồng bộ thể chế và nâng chất lượng tăng trưởng."},{"s":112.63,"e":123.29,"c":3,"t":"Bốn trụ cột: phát triển kinh tế xã hội là trung tâm; xây dựng Đảng là then chốt; phát triển văn hóa, con người là nền tảng tinh thần; tăng cường quốc phòng, an ninh là trọng yếu, thường xuyên."},{"s":123.39,"e":134.13,"c":3,"t":"Các nghị quyết Trung ương 4 khóa mười một và khóa mười hai về xây dựng, chỉnh đốn Đảng, ngăn chặn suy thoái tư tưởng chính trị, đạo đức, lối sống, tự diễn biến, tự chuyển hóa được thực hiện quyết liệt."},{"s":134.08,"e":141.14,"c":3,"t":"Phòng, chống tham nhũng không có vùng cấm, không có ngoại lệ; kỷ luật, kiểm tra và kiểm soát quyền lực trở thành nội dung trọng tâm."},{"s":141.24,"e":144.15,"c":4,"t":"Hội nhập thế hệ mới và thử thách đại dịch."},{"s":144.22,"e":158.7,"c":4,"t":"Việt Nam tham gia các hiệp định thương mại tự do thế hệ mới như Hiệp định Đối tác Toàn diện và Tiến bộ xuyên Thái Bình Dương có hiệu lực năm 2019, Hiệp định với Liên minh châu Âu có hiệu lực năm 2020; đồng thời tái cơ cấu ngân hàng, doanh nghiệp nhà nước, đầu tư công."},{"s":158.65,"e":164.07,"c":4,"t":"Lạm phát được kiểm soát, chỉ khoảng ba phẩy hai mươi ba phần trăm năm 2020."},{"s":164.16,"e":173.65,"c":4,"t":"Năm 2020, đại dịch COVID mười chín là cú sốc lớn, nhưng Việt Nam vẫn tăng trưởng dương; yêu cầu chuyển đổi số và khả năng chống chịu trở nên cấp thiết."},{"s":173.6,"e":180.2,"c":4,"t":"Bài học: đột phá chiến lược phải gắn với năng lực thực thi; phát triển kinh tế phải song hành với xây dựng Đảng và kiểm soát quyền lực."}]},"2021-2026":{"duration":223.1,"chapters":[{"title":"Mở đầu: hai cột mốc một trăm năm","target":"hero","start":0.0},{"title":"Đại hội lần thứ mười ba: khơi dậy khát vọng","target":"congress","start":17.28},{"title":"Bộ tứ chiến lược và tinh gọn bộ máy","target":"dossiers","start":66.22},{"title":"Đại hội lần thứ mười bốn: tự chủ chiến lược","target":"expert","start":127.13},{"title":"Kết luận: sợi chỉ đỏ xuyên suốt","target":"results","start":189.96}],"cues":[{"s":0.1,"e":9.19,"c":0,"t":"Phía trước là hai cột mốc một trăm năm: năm 2030, một trăm năm thành lập Đảng, và năm 2045, một trăm năm thành lập nước."},{"s":9.14,"e":13.79,"c":0,"t":"Làm thế nào để khát vọng một nước Việt Nam phát triển, thu nhập cao trở thành hiện thực?"},{"s":13.79,"e":17.26,"c":0,"t":"Đây là phần lịch sử đang được viết bởi chính thế hệ các bạn."},{"s":17.38,"e":20.72,"c":1,"t":"Đại hội lần thứ mười ba: khơi dậy khát vọng."},{"s":20.79,"e":32.71,"c":1,"t":"Đại hội lần thứ mười ba họp từ 25 tháng 1 đến 1 tháng 2 năm 2021, tổng kết ba mươi lăm năm đổi mới, ba mươi năm Cương lĩnh 1991 và mười năm Cương lĩnh 2011."},{"s":32.66,"e":46.47,"c":1,"t":"Mục tiêu: đến 2025 là nước đang phát triển có công nghiệp theo hướng hiện đại, vượt mức thu nhập trung bình thấp; đến 2030 có công nghiệp hiện đại, thu nhập trung bình cao; đến 2045 là nước phát triển, thu nhập cao."},{"s":46.56,"e":58.02,"c":1,"t":"Đại hội nhấn mạnh khát vọng phát triển đất nước phồn vinh, hạnh phúc; phát triển dựa nhiều hơn vào khoa học công nghệ, đổi mới sáng tạo và chuyển đổi số; xây dựng thế trận lòng dân, bảo vệ Tổ quốc từ sớm, từ xa."},{"s":57.97,"e":66.21,"c":1,"t":"Nhiệm kỳ bắt đầu giữa đại dịch: chính sách chuyển từ zero COVID sang thích ứng an toàn, linh hoạt, và đại dịch thúc đẩy chuyển đổi số mạnh mẽ."},{"s":66.32,"e":69.19,"c":2,"t":"Bộ tứ chiến lược và tinh gọn bộ máy."},{"s":69.24,"e":76.33,"c":2,"t":"Tháng 8 năm 2024, đồng chí Tô Lâm được bầu làm Tổng Bí thư, nêu tinh thần kỷ nguyên vươn mình của dân tộc."},{"s":76.28,"e":89.51,"c":2,"t":"Giai đoạn 2024 đến 2025 diễn ra cuộc sắp xếp, tinh gọn bộ máy với tinh thần tinh, gọn, mạnh, hiệu năng, hiệu lực, hiệu quả, cùng việc sắp xếp đơn vị hành chính và vận hành chính quyền địa phương hai cấp."},{"s":89.62,"e":92.27,"c":2,"t":"Bộ tứ chiến lược gồm bốn nghị quyết."},{"s":92.22,"e":100.63,"c":2,"t":"Nghị quyết 57 tháng 12 năm 2024 về khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số, yếu tố quyết định để phát triển."},{"s":100.63,"e":109.11,"c":2,"t":"Nghị quyết 59 tháng 1 năm 2025 về hội nhập quốc tế, nâng tầm hội nhập sang chất lượng, hiệu quả, gắn với tự chủ chiến lược."},{"s":109.11,"e":115.54,"c":2,"t":"Nghị quyết 66 tháng 4 năm 2025 về xây dựng và thi hành pháp luật, đột phá của đột phá."},{"s":115.54,"e":122.59,"c":2,"t":"Nghị quyết 68 tháng 5 năm 2025 về kinh tế tư nhân, một động lực quan trọng nhất của nền kinh tế quốc gia."},{"s":122.59,"e":127.13,"c":2,"t":"Cách nhớ: công nghệ, hội nhập, thể chế và khu vực tư nhân."},{"s":127.23,"e":130.5,"c":3,"t":"Đại hội lần thứ mười bốn: tự chủ chiến lược."},{"s":130.56,"e":142.39,"c":3,"t":"Từ 19 đến 23 tháng 1 năm 2026, Đại hội lần thứ mười bốn họp tại Hà Nội với một nghìn năm trăm tám mươi sáu đại biểu, đại diện hơn năm triệu sáu trăm nghìn đảng viên, tổng kết bốn mươi năm đổi mới."},{"s":142.34,"e":145.71,"c":3,"t":"Đồng chí Tô Lâm tiếp tục được bầu làm Tổng Bí thư."},{"s":145.83,"e":157.89,"c":3,"t":"Đại hội nhấn mạnh tự chủ chiến lược, tự lực, tự cường, phát triển nhanh và bền vững; khoa học công nghệ, đổi mới sáng tạo, chuyển đổi số là động lực chính; kinh tế số, kinh tế xanh, kinh tế tuần hoàn."},{"s":157.84,"e":170.33,"c":3,"t":"Mục tiêu 2026 đến 2030: tăng trưởng bình quân từ mười phần trăm mỗi năm trở lên, thu nhập bình quân đầu người khoảng tám nghìn năm trăm đô la Mỹ vào năm 2030, kinh tế số khoảng ba mươi phần trăm."},{"s":170.43,"e":176.72,"c":3,"t":"Hiểu đúng: tự chủ không có nghĩa là khép kín, mà là nội lực mạnh để hội nhập sâu mà vẫn chống chịu được biến động."},{"s":176.67,"e":189.96,"c":3,"t":"Sau Đại hội, các Hội nghị Trung ương 2, 3 và 4 khóa mười bốn tiếp tục cụ thể hóa nghị quyết; Hội nghị Trung ương 4, tháng 10 năm 2026, tập trung xây dựng, chỉnh đốn Đảng và hệ thống chính trị trong sạch, vững mạnh toàn diện."},{"s":190.06,"e":192.88,"c":4,"t":"Kết luận: sợi chỉ đỏ xuyên suốt."},{"s":192.94,"e":198.52,"c":4,"t":"Nhìn lại gần một trăm năm, sợi chỉ đỏ xuyên suốt là độc lập dân tộc gắn liền với chủ nghĩa xã hội."},{"s":198.47,"e":211.78,"c":4,"t":"Đường lối chỉ đúng khi xuất phát từ thực tiễn và xác định đúng mâu thuẫn chủ yếu; sự lãnh đạo của Đảng được kiểm nghiệm ở năng lực tổ chức, tự điều chỉnh và sửa sai; sức mạnh dân tộc phát huy cao nhất khi kết hợp nội lực với sức mạnh thời đại; và đổi mới là quá trình liên tục."},{"s":211.9,"e":217.17,"c":4,"t":"Như lời Bác Hồ dặn: dân ta phải biết sử ta, cho tường gốc tích nước nhà Việt Nam."},{"s":217.12,"e":220.91,"c":4,"t":"Học lịch sử Đảng là để hiểu con đường đã đi và tự tin bước tiếp."},{"s":220.91,"e":223.05,"c":4,"t":"Cảm ơn các bạn đã lắng nghe."}]},"pre1930":{"duration":302.7,"chapters":[{"title":"Mở đầu: một câu hỏi lớn","target":"hero","start":0.0},{"title":"Bối cảnh: xã hội thuộc địa nửa phong kiến","target":"context","start":23.02},{"title":"Những con đường cứu nước đi vào bế tắc","target":"movements","start":71.69},{"title":"Nguyễn Ái Quốc tìm ra con đường mới","target":"deep","start":115.32},{"title":"Hội nghị hợp nhất và Cương lĩnh chính trị đầu tiên","target":"dossiers","start":194.74},{"title":"Kết luận: ý nghĩa sự ra đời của Đảng","target":"results","start":268.08}],"cues":[{"s":0.1,"e":2.02,"c":0,"t":"Xin chào các bạn."},{"s":1.97,"e":13.19,"c":0,"t":"Vì sao suốt hơn bảy mươi năm, từ khi thực dân Pháp nổ súng xâm lược năm 1858, biết bao phong trào yêu nước nổ ra, biết bao người con ưu tú ngã xuống, mà đất nước vẫn chưa thoát khỏi vòng nô lệ?"},{"s":13.19,"e":18.01,"c":0,"t":"Và vì sao đến mùa xuân năm 1930, cách mạng mới tìm được lối ra?"},{"s":18.01,"e":23.0,"c":0,"t":"Câu trả lời không nằm ở lòng yêu nước, mà ở hai chữ: đường lối và tổ chức."},{"s":23.12,"e":26.38,"c":1,"t":"Bối cảnh: xã hội thuộc địa nửa phong kiến."},{"s":26.43,"e":30.36,"c":1,"t":"Sau khi xâm lược, thực dân Pháp khai thác thuộc địa quy mô lớn."},{"s":30.31,"e":36.68,"c":1,"t":"Về chính trị, chủ quyền quốc gia bị xâm phạm, bộ máy phong kiến bị đặt dưới sự chi phối của chính quyền thuộc địa."},{"s":36.68,"e":44.01,"c":1,"t":"Về kinh tế, xuất hiện một số yếu tố tư bản chủ nghĩa nhưng nền kinh tế lệ thuộc, mất cân đối, phục vụ lợi ích tư bản Pháp."},{"s":44.01,"e":48.13,"c":1,"t":"Về xã hội, chính sách giáo dục và cai trị làm phân hóa sâu sắc."},{"s":48.24,"e":57.18,"c":1,"t":"Giai cấp địa chủ cấu kết với thực dân, nông dân bị bần cùng hóa, và giai cấp công nhân Việt Nam ra đời, chịu ba tầng áp bức nên có tinh thần cách mạng triệt để."},{"s":57.13,"e":68.75,"c":1,"t":"Xã hội Việt Nam trở thành xã hội thuộc địa nửa phong kiến, với hai mâu thuẫn cơ bản: mâu thuẫn giữa toàn thể dân tộc Việt Nam với thực dân và tay sai, đây là mâu thuẫn nổi bật nhất; và mâu thuẫn giữa nông dân với địa chủ phong kiến."},{"s":68.75,"e":71.68,"c":1,"t":"Yêu cầu lịch sử trước hết là giành lại độc lập."},{"s":71.79,"e":74.52,"c":2,"t":"Những con đường cứu nước đi vào bế tắc."},{"s":74.57,"e":79.6,"c":2,"t":"Năm 1885, vua Hàm Nghi và Tôn Thất Thuyết ra Chiếu Cần Vương."},{"s":79.55,"e":86.39,"c":2,"t":"Các cuộc khởi nghĩa Ba Đình, Bãi Sậy, Hương Khê rất anh dũng, nhưng ngọn cờ phong kiến đã lỗi thời nên lần lượt thất bại."},{"s":86.39,"e":97.14,"c":2,"t":"Đầu thế kỷ hai mươi, khuynh hướng dân chủ tư sản xuất hiện: Phan Bội Châu với phong trào Đông Du, Phan Châu Trinh với cuộc vận động Duy Tân, Đông Kinh Nghĩa Thục, rồi Việt Nam Quốc dân Đảng với khởi nghĩa Yên Bái."},{"s":97.14,"e":99.2,"c":2,"t":"Tất cả đều thất bại."},{"s":99.32,"e":103.2,"c":2,"t":"Các bạn cần hiểu đúng: thất bại ấy không phủ định lòng yêu nước."},{"s":103.15,"e":108.84,"c":2,"t":"Nó phản ánh giới hạn của những hệ tư tưởng và cách tổ chức chưa đủ sức tập hợp, lãnh đạo toàn dân."},{"s":108.84,"e":115.31,"c":2,"t":"Đất nước rơi vào khủng hoảng sâu sắc về đường lối cứu nước và về lực lượng lãnh đạo, tình hình đen tối như không có đường ra."},{"s":115.42,"e":118.01,"c":3,"t":"Nguyễn Ái Quốc tìm ra con đường mới."},{"s":118.08,"e":124.33,"c":3,"t":"Ngày 5 tháng 6 năm 1911, người thanh niên Nguyễn Tất Thành rời bến Nhà Rồng ra đi tìm đường cứu nước."},{"s":124.28,"e":131.62,"c":3,"t":"Khác các bậc tiền bối, Người không cầu viện, mà khảo nghiệm thực tiễn ở nhiều nước, tiếp xúc phong trào công nhân và phong trào giải phóng dân tộc."},{"s":131.62,"e":139.27,"c":3,"t":"Năm 1919, Người gửi Bản yêu sách của nhân dân An Nam tới Hội nghị Véc xây, đòi những quyền dân tộc và dân chủ tối thiểu."},{"s":139.37,"e":149.37,"c":3,"t":"Mốc quyết định là tháng 7 năm 1920, khi Người đọc bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lênin, tìm thấy con đường cách mạng vô sản."},{"s":149.32,"e":157.64,"c":3,"t":"Tháng 12 năm ấy, tại Đại hội Tua, Người tán thành Quốc tế thứ ba, tham gia sáng lập Đảng Cộng sản Pháp, chuyển từ người yêu nước thành người cộng sản."},{"s":157.76,"e":160.7,"c":3,"t":"Từ đó, Người chuẩn bị trên ba mặt."},{"s":160.65,"e":168.74,"c":3,"t":"Thứ nhất, về tư tưởng: tham gia Hội Liên hiệp thuộc địa, viết cho báo Người cùng khổ, truyền bá chủ nghĩa Mác Lênin và phê phán chủ nghĩa thực dân."},{"s":168.74,"e":176.68,"c":3,"t":"Thứ hai, về chính trị: xác lập các luận điểm về giải phóng dân tộc, lực lượng cách mạng, vai trò của Đảng và quan hệ với cách mạng thế giới."},{"s":176.68,"e":187.34,"c":3,"t":"Thứ ba, về tổ chức: tháng 6 năm 1925, lập Hội Việt Nam Cách mạng Thanh niên tại Quảng Châu, mở lớp huấn luyện cán bộ, ra báo Thanh Niên, phát động phong trào vô sản hóa."},{"s":187.34,"e":194.73,"c":3,"t":"Tác phẩm Đường Kách mệnh năm 1927 khẳng định: cách mạng trước hết phải có đảng cách mệnh, đảng có vững cách mệnh mới thành công."},{"s":194.84,"e":198.15,"c":4,"t":"Hội nghị hợp nhất và Cương lĩnh chính trị đầu tiên."},{"s":198.2,"e":208.31,"c":4,"t":"Năm 1929, phong trào công nhân và yêu nước lên cao, ba tổ chức cộng sản ra đời: Đông Dương Cộng sản Đảng, An Nam Cộng sản Đảng và Đông Dương Cộng sản Liên đoàn."},{"s":208.26,"e":213.22,"c":4,"t":"Đây là bước trưởng thành, nhưng các tổ chức hoạt động riêng rẽ, tranh giành ảnh hưởng."},{"s":213.22,"e":216.2,"c":4,"t":"Yêu cầu bức thiết là thống nhất thành một đảng."},{"s":216.32,"e":229.88,"c":4,"t":"Đầu năm 1930, tại Hương Cảng, Trung Quốc, Nguyễn Ái Quốc với tư cách phái viên Quốc tế Cộng sản chủ trì Hội nghị hợp nhất, thành lập Đảng Cộng sản Việt Nam, thông qua Chánh cương vắn tắt, Sách lược vắn tắt, Chương trình tóm tắt và Điều lệ vắn tắt."},{"s":229.83,"e":234.14,"c":4,"t":"Ngày 3 tháng 2 năm 1930 được lấy làm ngày thành lập Đảng."},{"s":234.24,"e":241.15,"c":4,"t":"Cương lĩnh chính trị đầu tiên xác định phương hướng: làm tư sản dân quyền cách mạng và thổ địa cách mạng để đi tới xã hội cộng sản."},{"s":241.1,"e":247.34,"c":4,"t":"Nhiệm vụ: đánh đổ đế quốc và phong kiến, trong đó chống đế quốc, giành độc lập được đặt ở vị trí nổi bật."},{"s":247.34,"e":253.64,"c":4,"t":"Lực lượng: công nhân và nông dân là nền tảng, đồng thời tập hợp, lôi kéo hoặc trung lập các tầng lớp khác."},{"s":253.64,"e":256.78,"c":4,"t":"Lãnh đạo: Đảng Cộng sản là đội tiên phong."},{"s":256.78,"e":261.01,"c":4,"t":"Quốc tế: cách mạng Việt Nam là một bộ phận của cách mạng thế giới."},{"s":261.01,"e":268.08,"c":4,"t":"Giá trị lớn nhất là kết hợp mục tiêu giai cấp với yêu cầu dân tộc, vận dụng sáng tạo chủ nghĩa Mác Lênin vào điều kiện Việt Nam."},{"s":268.18,"e":271.28,"c":5,"t":"Kết luận: ý nghĩa sự ra đời của Đảng."},{"s":271.35,"e":276.92,"c":5,"t":"Đảng ra đời là kết quả kết hợp chủ nghĩa Mác Lênin với phong trào công nhân và phong trào yêu nước Việt Nam."},{"s":276.87,"e":292.12,"c":5,"t":"Ý nghĩa cần nhớ: chấm dứt cuộc khủng hoảng kéo dài hơn hai phần ba thế kỷ về đường lối cứu nước và tổ chức lãnh đạo; xác lập vai trò lãnh đạo của giai cấp công nhân thông qua Đảng; gắn phong trào công nhân và phong trào yêu nước trong một tổ chức thống nhất; và đặt cơ sở đường lối cho toàn bộ cách mạng Việt Nam về sau."},{"s":292.23,"e":302.78,"c":5,"t":"Khi làm bài tự luận, hãy trình bày theo mạch: bối cảnh, sự thất bại của các khuynh hướng cũ, vai trò chuẩn bị của Nguyễn Ái Quốc, Hội nghị thành lập Đảng, nội dung Cương lĩnh và ý nghĩa lịch sử."}]}};
